    16→export const RoomListProvider = () => {
    17→  const client = useAtomValue(MatrixAtoms.matrixClient);
    18→  const syncService = useAtomValue(MatrixAtoms.syncService);
    19→  const setIsLoading = useSetAtom(MatrixAtoms.roomListLoading);
    20→
    21→  useEffect(() => {
    22→    if (!client || !syncService) return;
    23→
    24→    const initRoomListService = async () => {
    25→      try {
    26→        // Get the room list service
    27→        const roomListService = syncService.roomListService();
    28→        if (!roomListService) return null;
    29→
    30→        // Initial room fetch
    31→        await MatrixCore.refreshRoomList();
    32→
    33→        // Set up room list service state listener
    34→        const handle = roomListService.state({
    35→          onUpdate: (state: RoomListServiceState) => {
    36→            if (
    37→              state === RoomListServiceState.SettingUp ||
    38→              state === RoomListServiceState.Initial ||
    39→              state === RoomListServiceState.Recovering
    40→            ) {
    41→              setIsLoading(true);
    42→              Toast.show({
    43→                type: "info",
    44→                text1: "Syncing rooms...",
    45→                autoHide: false,
    46→              });
    47→            }
    48→
    49→            if (state === RoomListServiceState.Running) {
    50→              MatrixCore.refreshRoomList().then(() => {
    51→                setIsLoading(false);
    52→                Toast.hide();
    53→              });
    54→            }
    55→          },
    56→        });
    57→
    58→        return handle;
    59→      } catch (error) {
    60→        console.error("Failed to initialize room list service:", error);
    61→        return null;
    62→      } finally {
    63→        setIsLoading(false);
    64→      }
    65→    };
    66→
    67→    let handle: TaskHandleInterface | null = null;
    68→    initRoomListService().then((h) => {
    69→      handle = h;
    70→    });
    71→
    72→    return () => {
    73→      handle?.cancel?.();
    74→    };
    75→  }, [client, syncService]);
    76→
    77→  return <></>;
    78→};
