     9→import { MatrixJotaiStore } from "../const/matrx-jotai-store";
    10→import { MatrixAtoms } from "../jotai";
    11→
    12→export class MatrixCore {
    13→  public static instance: ClientInterface | null = null;
    14→  public static syncService: SyncServiceInterface | null = null;
    15→  public static profile: UserProfile | null = null;
    16→
    17→  /** Returns the client or throws if not initialized. Eliminates per-method null checks. */
    18→  public static getClient(): ClientInterface {
    19→    if (!MatrixCore.instance) {
    20→      throw new Error("Matrix client is not initialized");
    21→    }
    22→    return MatrixCore.instance;
    23→  }
    24→
    25→  /** Returns the room or throws. Use instead of getClient().getRoom() + manual null check. */
    26→  public static getRoom(roomId: string): RoomInterface {
    27→    const room = MatrixCore.getClient().getRoom(roomId);
    28→    if (!room) throw new Error(`Room not found: ${roomId}`);
    29→    return room;
    30→  }
    31→
    32→  public static getServerName = () => {
    33→    if (!MatrixCore.instance) return null;
    34→    return MatrixCore.instance.server() || MatrixCore.instance.homeserver();
    35→  };
    36→
    37→  /** Sort and store the current room list into Jotai. Called after any membership change. */
    38→  public static refreshRoomList = async () => {
    39→    if (!MatrixCore.instance) return;
    40→
    41→    try {
    42→      const rooms = MatrixCore.instance.rooms();
    43→
    44→      const sortedRooms = await Promise.all(
    45→        rooms.map(async (room) => ({
    46→          room,
    47→          timestamp: (await room.latestEvent())?.timestamp || 0,
    48→        })),
    49→      );
    50→
    51→      const filteredAndSortedRooms = sortedRooms
    52→        .filter(({ room }) => {
    53→          const membership = room.membership();
    54→          return (
    55→            membership !== Membership.Banned &&
    56→            membership !== Membership.Left &&
    57→            membership !== Membership.Knocked
    58→          );
    59→        })
    60→        .sort((a, b) => {
    61→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
    62→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
    63→          if (aInvited !== bInvited) return bInvited - aInvited;
    64→          return Number(b.timestamp) - Number(a.timestamp);
    65→        });
    66→
    67→      MatrixJotaiStore.set(
    68→        MatrixAtoms.roomList,
    69→        filteredAndSortedRooms.map(({ room }) => room),
    70→      );
    71→
    72→      const roomInfoEntries = await Promise.allSettled(
    73→        filteredAndSortedRooms.map(async ({ room }) => ({
    74→          id: room.id(),
    75→          info: await room.roomInfo(),
    76→        })),
    77→      );
    78→
    79→      const map = new Map<string, RoomInfo>();
    80→      for (const result of roomInfoEntries) {
    81→        if (result.status === "fulfilled") {
    82→          map.set(result.value.id, result.value.info);
    83→        }
    84→      }
    85→      MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, map);
    86→    } catch (error) {
    87→      console.error("Failed to refresh room list:", error);
    88→    }
    89→  };
    90→}
