    19→export const Rooms: FC<Props> = ({ search }) => {
    20→  const { value: filter } = useActiveFilter();
    21→  const { value: securityFilter } = useSecurityFilter();
    22→  const rooms = useAtomValue(MatrixAtoms.roomList);
    23→  const roomInfoMap = useAtomValue(MatrixAtoms.roomInfoMap);
    24→  const isLoading = useAtomValue(MatrixAtoms.roomListLoading);
    25→  const filteredRooms = useMemo(() => {
    26→    const filtered = rooms.filter((room) => {
    27→      if (!room?.displayName()?.toLowerCase()?.includes(search.toLowerCase()))
    28→        return false;
    29→
    30→      // For now there is no secure chats, so we show all chats
    31→      if (securityFilter === "secure") return false;
    32→
    33→      if (securityFilter === "unsecure") return true;
    34→
    35→      return true;
    36→    });
    37→
    38→    if (filter === "all") return filtered;
    39→
    40→    if (filter === "unread") {
    41→      return filtered.filter((room) => {
    42→        const info = roomInfoMap.get(room.id());
    43→        return !!Number(info?.numUnreadNotifications) || !!info?.isMarkedUnread;
    44→      });
    45→    }
    46→
    47→    if (filter === "favorites") {
    48→      return filtered.filter(
    49→        (room) => !!roomInfoMap.get(room.id())?.isFavourite,
    50→      );
    51→    }
    52→
    53→    if (filter === "direct") {
    54→      return filtered.filter((room) => !!roomInfoMap.get(room.id())?.isDirect);
    55→    }
    56→
    57→    if (filter === "rooms") {
    58→      return filtered.filter((room) => {
    59→        const info = roomInfoMap.get(room.id());
    60→        return !info?.isDirect && room.membership() !== Membership.Invited;
    61→      });
    62→    }
    63→
    64→    if (filter === "invites") {
    65→      return filtered.filter(
    66→        (room) => room.membership() === Membership.Invited,
    67→      );
    68→    }
    69→
    70→    return filtered;
    71→  }, [search, rooms, roomInfoMap, filter, securityFilter]);
    72→
    73→  const emptyText = useMemo(() => {
    74→    if (filter === "unread") return "No Unread Messages";
    75→    if (filter === "favorites") return "No Favorite Rooms";
    76→    if (filter === "direct") return "No Direct Messages";
    77→    if (filter === "rooms") return "No Rooms Found";
    78→    if (filter === "invites") return "No Pending Invites";
    79→    return "No Messages Found";
    80→  }, [filter]);
    81→
    82→  const keyExtractor = useCallback((item: RoomInterface) => item.id(), []);
    83→
    84→  const renderItem = useCallback(
    85→    ({ item }: ListRenderItemInfo<RoomInterface>) => (
    86→      <RoomsListItem room={item} />
    87→    ),
    88→    [],
    89→  );
    90→
    91→  const listEmptyComponent = useMemo(
    92→    () => (
    93→      <Block
    94→        align="center"
    95→        justify="center"
    96→        paddings={20}
    97→        margins={{ marginVertical: "auto" }}
    98→      >
    99→        <Image
   100→          source={require("assets/images/envelope.png")}
   101→          width={100}
   102→          height={100}
   103→        />
   104→        <Text
   105→          size={TextSize.large}
   106→          textAlign="center"
   107→          margins={{ marginBottom: 8, marginTop: 40 }}
   108→        >
   109→          {emptyText}
   110→        </Text>
   111→      </Block>
   112→    ),
   113→    [emptyText],
   114→  );
   115→
   116→  if (isLoading && !rooms.length) return <Loading text="Syncing..." />;
   117→
   118→  if (!rooms.length) return null;
   119→
   120→  return (
   121→    <FlatList
   122→      data={filteredRooms}
   123→      keyExtractor={keyExtractor}
   124→      renderItem={renderItem}
   125→      ListEmptyComponent={listEmptyComponent}
   126→    />
   127→  );
   128→};
