    16→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
    17→  navigation,
    18→}) => {
    19→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    20→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
    21→  const hasSeenNotificationsIntro = useAtomValue(
    22→    PushNotificationsAtoms.hasSeenNotificationsIntro,
    23→  );
    24→  const transition = useRef(
    25→    animateParallel(
    26→      { opacity: [0, 1], translateY: [40, 0] },
    27→      { duration: 200 },
    28→    ),
    29→  ).current;
    30→
    31→  useEffect(() => {
    32→    const checkAuthAndNavigate = async () => {
    33→      try {
    34→        // Check if we have stored credentials
    35→        if (AuthService.hasStoredCredentials()) {
    36→          const sessionRestored = await AuthService.restoreSession();
    37→          const isVerified = VerificationService.isDeviceVerified();
    38→
    39→          if (sessionRestored && !isVerified) {
    40→            navigation.replace("confirmIdentity");
    41→            return;
    42→          }
    43→
    44→          if (!hasSeenOnboarding) {
    45→            navigation.replace("onboarding");
    46→            return;
    47→          }
    48→
    49→          if (!hasSeenNotificationsIntro) {
    50→            navigation.replace("notificationsIntro");
    51→            return;
    52→          }
    53→
    54→          //If there is a screen lock pin, navigate to the verify pin screen
    55→          if (screenLockPin && sessionRestored) {
    56→            navigation.replace("verifyPin", { isSettingsScreen: false });
    57→            return;
    58→          }
    59→
    60→          if (sessionRestored) {
    61→            // Start sync — no-op if offline, rooms are served from local cache
    62→            AuthService.startSync();
    63→
    64→            // Check if app was opened from a notification
    65→            const pendingRoomId = NotifeeService.consumePendingRoomId();
    66→            await MatrixCore.refreshRoomList();
    67→            if (pendingRoomId) {
    68→              navigation.reset({
    69→                index: 1,
    70→                routes: [
    71→                  { name: "home" },
    72→                  { name: "room", params: { roomId: pendingRoomId } },
    73→                ],
    74→              });
    75→              return;
    76→            }
    77→
    78→            navigation.replace("home");
    79→            return;
    80→          }
    81→        }
    82→
    83→        await AuthService.initialize(MatrixBaseURL);
    84→        navigation.replace("welcome");
    85→      } catch (error) {
    86→        console.warn("Error during auth check:", error);
    87→        navigation.replace("welcome");
    88→      }
    89→    };
    90→
    91→    transition.start(() => {
    92→      setTimeout(checkAuthAndNavigate, 2000);
    93→    });
    94→  }, [navigation, hasSeenOnboarding, screenLockPin, transition]);
    95→
    96→  return (
    97→    <ScreenLayout>
    98→      <Block
    99→        animations={transition.animations}
   100→        flex={1}
   101→        align="center"
   102→        justify="space-between"
   103→      >
   104→        <Image
   105→          source={require("assets/images/logo.png")}
   106→          width={88}
   107→          height={66}
   108→          style={styles.logo}
   109→        />
   110→        <Text font="Silkscreen-Regular" size={TextSize.medium}>
   111→          CLOAK
   112→        </Text>
   113→      </Block>
   114→    </ScreenLayout>
   115→  );
   116→};
   117→
