    29→/** Get the current user ID, works in both foreground and background */
    30→const getCurrentUserId = (): string | null => {
    31→  // Try to get from active instance first (foreground)
    32→  const instanceUserId = MatrixCore.instance?.userId();
    33→  if (instanceUserId) return instanceUserId;
    34→
    35→  // Fall back to stored credentials (works in background)
    36→  const credentials = MatrixStorage.getLoginCredentials();
    37→  return credentials?.userId || null;
    38→};
    39→
    40→/**
    41→ * Ensure MatrixService is initialized for background decryption
    42→ * Uses lightweight initialization that doesn't start sync service
    43→ */
    44→const ensureServiceInitialized = async (): Promise<boolean> => {
    45→  const notificationClient = MatrixNotificationService.getNotificationClient();
    46→  if (notificationClient) return true;
    47→
    48→  // Foreground: create notification client if possible
    49→  if (MatrixCore.instance) {
    50→    const client = await MatrixNotificationService.ensureNotificationClient();
    51→    return !!client;
    52→  }
    53→
    54→  // Try to restore session with lightweight background method
    55→  try {
    56→    const restored = await AuthService.restoreSessionForBackground();
    57→    return restored;
    58→  } catch (error) {
    59→    console.error("[Push] Failed to restore session:", error);
    60→    return false;
    61→  }
    62→};
    63→
    64→const handleReceivedMessage = async (
    65→  message: FirebaseMessagingTypes.RemoteMessage,
    66→) => {
    67→  const data = message.data as unknown as NotificationData;
    68→  if (!data) return;
    69→
    70→  // Skip notifications for own messages (works in both foreground and background)
    71→  const currentUserId = getCurrentUserId();
    72→  if (currentUserId && data.sender === currentUserId) return;
    73→
    74→  const isCallOnIOS =
    75→    Platform.OS === "ios" &&
    76→    (data.type === "m.call.invite" ||
    77→      data.type === "m.call.member" ||
    78→      data.type === "m.rtc.notification");
    79→
    80→  if (isCallOnIOS) {
    81→    // Skip if sync-based detection already triggered CallKit for this room
    82→    if (CallKitService.isRingingForRoom(data.room_id)) return;
    83→
    84→    CallKitService.displayIncomingCall({
    85→      roomId: data.room_id,
    86→      roomName: data.room_name || data.sender_display_name || data.sender,
    87→      senderDisplayName: data.sender_display_name || data.sender,
    88→    });
    89→    return;
    90→  }
    91→
    92→  const notificationId = message.messageId || `msg_${Date.now()}`;
    93→  const formattedMessage = formatLocalPushNotificationMessage(data);
    94→
    95→  if (!formattedMessage) return;
    96→
    97→  // Decrypt encrypted messages, then check if it's a call or a regular message
    98→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    99→    try {
   100→      // Always ensure service is initialized for encrypted messages
   101→      const initialized = await ensureServiceInitialized();
   102→      if (!initialized) return;
   103→
   104→      // Check if the decrypted event is a call — route to CallKit on iOS
   105→      if (Platform.OS === "ios") {
   106→        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);
   107→
   108→        if (isCall) {
   109→          // Skip if sync-based detection already triggered CallKit for this room
   110→          if (CallKitService.isRingingForRoom(data.room_id)) return;
   111→
   112→          const roomName = RoomService.getRoomInfo(
   113→            data.room_id,
   114→          )?.displayName();
   115→
   116→          CallKitService.displayIncomingCall({
   117→            roomId: data.room_id,
   118→            roomName:
   119→              roomName ||
   120→              data.room_name ||
   121→              data.sender_display_name ||
   122→              data.sender,
   123→            senderDisplayName: data.sender_display_name || data.sender,
   124→          });
   125→          return;
   126→        }
   127→      }
   128→
   129→      const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
   130→      const decryptedContent = await getDecryptedEventContent(
   131→        data.room_id,
   132→        data.event_id,
   133→      );
   134→
   135→      if (decryptedContent) {
   136→        await NotifeeService.create({
   137→          title:
   138→            roomName ||
   139→            data.room_name ||
   140→            data.sender_display_name ||
   141→            data.sender ||
   142→            "Unknown Sender",
   143→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
   144→          id: notificationId,
   145→          data: { room_id: data.room_id },
   146→        });
   147→      } else {
   148→        await NotifeeService.create({
   149→          title: formattedMessage.title,
   150→          message: formattedMessage.message,
   151→          id: notificationId,
   152→          data: { room_id: formattedMessage.room_id },
   153→        });
   154→      }
   155→    } catch (error) {
   156→      console.error("[Push] Failed to decrypt:", error);
   157→    }
   158→
   159→    return;
   160→  }
   161→
   162→  // For non-encrypted messages, show directly
   163→  await NotifeeService.create({
   164→    title: formattedMessage.title,
   165→    message: formattedMessage.message,
   166→    id: notificationId,
   167→    data: { room_id: formattedMessage.room_id },
   168→  });
   169→};
   170→
   171→const handleNotificationPress = async (
   172→  message: FirebaseMessagingTypes.RemoteMessage | null,
   173→  isInitialNotification: boolean,
   174→) => {
   175→  const data = message?.data as unknown as NotificationData;
   176→  const roomId = data?.room_id;
   177→
   178→  if (!roomId || typeof roomId !== "string") return;
   179→
   180→  // For initial notification (cold start), store the room_id
   181→  // and let the Splash screen handle navigation after session restoration
   182→  if (isInitialNotification) {
   183→    NotifeeService.setPendingRoomId(roomId);
   184→    return;
   185→  }
   186→
   187→  // Refresh the room list before navigating to ensure it's up to date
   188→  await MatrixCore.refreshRoomList();
   189→
   190→  // For background events (app already running), navigate directly to room
   191→  NavigationContainerRef.navigate("room", { roomId });
   192→};
