   194→export const PushNotificationsService = {
   195→  getToken: async () => await getToken(getMessaging()),
   196→  /** Register the device with Matrix homeserver for push notifications
   197→   * This should be called after successful login and after push permissions */
   198→  registerPusher: async () => {
   199→    try {
   200→      const fcmToken = await getToken(getMessaging());
   201→      await MatrixNotificationService.setPusher(fcmToken);
   202→      return true;
   203→    } catch (error) {
   204→      console.error("Failed to register push notifications:", error);
   205→      throw error;
   206→    }
   207→  },
   208→  /** Unregister the device from Matrix homeserver */
   209→  unregisterPusher: async () => {
   210→    try {
   211→      const fcmToken = await getMessaging().getToken();
   212→      await MatrixNotificationService.removePusher(fcmToken);
   213→      return true;
   214→    } catch (error) {
   215→      console.error("Failed to unregister push notifications:", error);
   216→      throw error;
   217→    }
   218→  },
   219→  registerListeners: async () => {
   220→    // Foreground message handler
   221→    onMessage(getMessaging(), async (message) => {
   222→      await handleReceivedMessage(message);
   223→    });
   224→
   225→    // When the application is opened from a quit state (cold start)
   226→    getInitialNotification(getMessaging()).then((remoteMessage) => {
   227→      handleNotificationPress(remoteMessage, true);
   228→    });
   229→
   230→    // When the application is running, but in the background
   231→    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
   232→      handleNotificationPress(remoteMessage, false);
   233→    });
   234→  },
   235→  /** Handle background messages - called from index.js */
   236→  handleBackgroundMessage: async (
   237→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
   238→  ) => {
   239→    await handleReceivedMessage(remoteMessage);
   240→  },
   241→  checkPermissions: async () => {
   242→    const result = await checkNotifications();
   243→    return result.status === RESULTS.GRANTED;
   244→  },
   245→  requestPermissions: async () => {
   246→    const result = await requestNotifications(["alert"]);
   247→    return result.status === RESULTS.GRANTED;
   248→  },
   249→  subscribeToTopic: async (topic: string) => {
   250→    await getMessaging().subscribeToTopic(topic);
   251→  },
   252→  unsubscribeFromTopic: async (topic: string) => {
   253→    await getMessaging().unsubscribeFromTopic(topic);
   254→  },
   255→};
