    23→  useEffect(() => {
    24→    if (Platform.OS !== "ios" || roomList.length === 0) return;
    25→
    26→    const currentActiveCallRoomIds = new Set<string>();
    27→
    28→    for (const room of roomList) {
    29→      if (!room.hasActiveRoomCall()) return;
    30→      currentActiveCallRoomIds.add(room.id());
    31→    }
    32→
    33→    // Detect newly active calls (rooms that weren't active before)
    34→    for (const roomId of currentActiveCallRoomIds) {
    35→      if (prevActiveCallRoomIds.current.has(roomId)) continue;
    36→
    37→      // Don't show CallKit if we initiated the call ourselves
    38→      if (ElementCallService.getActiveCallRoomId() === roomId) continue;
    39→
    40→      // Don't show if already ringing for this room (e.g. from push)
    41→      if (CallKitService.isRingingForRoom(roomId)) continue;
    42→
    43→      // Get room info for display
    44→      const roomInfo = RoomService.getRoomInfo(roomId);
    45→      const roomName = roomInfo?.displayName() ?? "Unknown Room";
    46→      const currentUserId = MatrixCore.instance?.userId();
    47→
    48→      // Don't ring for own calls
    49→      if (!currentUserId) continue;
    50→
    51→      CallKitService.displayIncomingCall({
    52→        roomId,
    53→        roomName,
    54→        senderDisplayName: roomName,
    55→      });
    56→    }
    57→
    58→    prevActiveCallRoomIds.current = currentActiveCallRoomIds;
    59→  }, [roomList]);
    60→
    61→  return <></>;
    62→};
